const EVENTS = [
  { y: -44, mo: 3, t: '恺撒的葬礼', p: '罗马广场', m: '今意大利罗马', ll: [12.486, 41.892], k: 'pol', refs: ['普鲁塔克·安东尼传', '阿庇安·内战'],
    d: '刺杀之后两天，元老院在安东尼的主持下达成妥协：不追究刺客，也不废除恺撒的法令。恺撒的遗嘱公开了，他给每个罗马公民留下三百塞斯特斯，把台伯河对岸的花园捐作公园，指定甥孙盖乌斯·屋大维为主要继承人并收为养子。葬礼上，执政官安东尼致悼词，普鲁塔克说，他看到民众被打动，便在悼词末尾**把死者的衣服高高抖开，衣服上满是血迹，被刀剑割得破烂不堪||shook on high the garments of the dead, all bloody and tattered by the swords as they were**，人群怒不可遏，搬来长凳和桌子，就在广场上火化了恺撒的遗体，又举着火把去烧刺客的房子。布鲁图斯与卡西乌斯不久离开了罗马。',
    who: ['安东尼', '马库斯·布鲁图斯', '卡西乌斯'] },
  { y: -44, mo: 5, t: '屋大维来到罗马', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['阿庇安·内战', '苏埃托尼乌斯·奥古斯都传'],
    d: '恺撒遇刺时，十八岁的屋大维正在伊利里亚海岸的阿波罗尼亚读书，等着随恺撒远征帕提亚。他不顾母亲与继父的劝阻，接受了遗嘱和“恺撒”的名字，渡海回到意大利，一路上恺撒的老兵纷纷来投。到了罗马，他要求安东尼交出恺撒的财产好兑现遗赠，安东尼对这个“靠一个名字起家的孩子”不屑一顾。屋大维便变卖自己的家产，按遗嘱给民众发钱，从此人们称他“恺撒”。他的同学阿格里帕一直跟在他身边。',
    who: ['奥古斯都', '安东尼', '阿格里帕'] },
  { y: -44, mo: 7, t: '恺撒之星', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'cul', refs: ['苏埃托尼乌斯·恺撒传', '苏埃托尼乌斯·奥古斯都传'],
    d: '七月，屋大维自己出钱为恺撒举办胜利女神赛会。苏埃托尼乌斯说，赛会期间，**一颗彗星连续七天出现，总在十一点钟前后升起，人们认为那是恺撒的灵魂被接进了天上||a comet blazed for seven days together, rising always about eleven o\'clock; and it was supposed to be the soul of Caesar, now received into heaven**。屋大维借此宣布恺撒成了神，从此在恺撒雕像的头上加一颗星，自称“神之子”。这颗“尤利乌斯之星”后来出现在罗马的钱币与诗歌里。',
    who: ['恺撒', '奥古斯都'], post: ['恺撒'] },
  { y: -44, mo: 9, t: '反腓力辞', p: '罗马元老院', m: '今意大利罗马', ll: [12.485, 41.893], k: 'pol', refs: ['普鲁塔克·西塞罗传', '普鲁塔克·安东尼传'],
    d: '安东尼借恺撒的文件随意颁授特权、拨用国库，又让民众大会把五年任期的山南高卢划给自己。六十二岁的西塞罗从隐居中回到元老院，九月起连续发表演说抨击安东尼，一共十四篇，模仿三百年前狄摩西尼抨击马其顿国王腓力的演说，称为“反腓力辞”。他把希望寄托在年轻的屋大维身上，以为可以利用这个孩子再把他抛开。',
    who: ['西塞罗', '安东尼', '奥古斯都'] },
  { y: -44, mo: 10, t: '屋大维私募军队', p: '坎帕尼亚', m: '今意大利那不勒斯一带', ll: [14.3, 40.9], k: 'war', refs: ['阿庇安·内战', '奥古斯都·功业录'],
    d: '屋大维没有任何官职，却到坎帕尼亚去找恺撒安置的老兵，每人给两千塞斯特斯，招来三千人；安东尼从马其顿调回的两个军团也倒向他。这完全是私人的军队，他晚年在《功业录》的开头为此辩解：在我十九岁那年，我自作主张、自己出钱募集了一支军队，**以此把被一个派系的专制压迫的共和国重新解放||by means of which I restored to liberty the commonwealth which had been oppressed by the tyranny of a faction**。',
    who: ['奥古斯都', '安东尼'] },
  { y: -44, mo: 12, t: '穆提那之围', p: '穆提那', m: '今意大利摩德纳', ll: [10.93, 44.65], k: 'war', refs: ['阿庇安·内战', '普鲁塔克·安东尼传'],
    d: '安东尼带兵北上，要从刺客之一德奇穆斯·布鲁图斯手里夺取山南高卢。德奇穆斯退守穆提那，被安东尼围困。元老院在西塞罗的鼓动下把安东尼宣布为公敌，授予屋大维代大法官的统帅权，与两位执政官希尔提乌斯、潘萨一道北上解围。',
    who: ['安东尼', '德奇穆斯·布鲁图斯', '奥古斯都', '西塞罗'] },
  { y: -43, mo: 4, t: '穆提那之战', p: '穆提那', m: '今意大利摩德纳', ll: [10.93, 44.65], k: 'war', refs: ['阿庇安·内战', '普鲁塔克·安东尼传', '苏埃托尼乌斯·奥古斯都传'],
    d: '四月，元老院的军队在高卢广场与穆提那城下两次击败安东尼，执政官潘萨与希尔提乌斯却先后伤重而死，有人怀疑是屋大维下的手。安东尼带着残兵翻越阿尔卑斯山，普鲁塔克说他在逃亡中喝浑水、吃野果，反而显出了吃苦的本色。元老院以为大局已定，把功劳全记在德奇穆斯名下，对屋大维冷淡下来。同时，布鲁图斯占领了马其顿与希腊，卡西乌斯夺取了叙利亚，东方的行省全落入“解放者”手中。',
    who: ['安东尼', '奥古斯都', '德奇穆斯·布鲁图斯', '马库斯·布鲁图斯', '卡西乌斯'] },
  { y: -43, mo: 5, t: '雷必达倒戈', p: '弗雷尤斯', m: '今法国弗雷瑞斯', ll: [6.74, 43.43], k: 'war', refs: ['阿庇安·内战', '普鲁塔克·安东尼传'],
    d: '安东尼来到外高卢，在阿尔根特乌斯河边与恺撒的骑兵长官、外高卢与近西班牙总督雷必达对垒。雷必达的士兵大多是恺撒的旧部，他们拆了营墙放安东尼进来。五月末两军合兵，不久统治长发高卢的普兰库斯与远西班牙的波利奥也带着军团投奔安东尼。德奇穆斯被部下抛弃，逃往马其顿途中被一个高卢酋长杀死。',
    who: ['雷必达', '安东尼', '德奇穆斯·布鲁图斯', '波利奥'] },
  { y: -43, mo: 8, t: '屋大维进军罗马', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['阿庇安·内战', '苏埃托尼乌斯·奥古斯都传'],
    d: '元老院拒绝让二十岁的屋大维破格担任执政官，他的百夫长便在元老院里撩开斗篷，按着剑说：“你们不给，这个会给。”屋大维带着八个军团渡过卢比孔河，罗马不战而降。八月十九日他当选执政官，同僚是他的堂兄佩迪乌斯。新执政官设立法庭，缺席审判刺杀恺撒的人，又撤销了对安东尼的公敌宣告。',
    who: ['奥古斯都'] },
  { y: -43, mo: 11, t: '后三头同盟', p: '博诺尼亚', m: '今意大利博洛尼亚附近的河洲', ll: [11.34, 44.49], k: 'pol', refs: ['阿庇安·内战', '普鲁塔克·安东尼传'],
    d: '十月，屋大维、安东尼、雷必达在博诺尼亚附近一条河中的小洲上会面，各带五个军团守在岸边，谈了两天。三人约定以“重建国家的三人委员会”的名义掌权五年，瓜分西方的行省：安东尼得高卢，雷必达得外高卢与西班牙，屋大维得阿非利加、西西里与撒丁岛，意大利共管，东方留待打败布鲁图斯与卡西乌斯之后再分。十一月，保民官提蒂乌斯在民众大会上通过《提蒂乌斯法》，使这个同盟合法化，史称“后三头”。屋大维娶了安东尼的继女克洛狄娅以示结好。西西里实际上落在了庞培的幼子塞克斯图斯手里，他的舰队控制着海路。',
    who: ['奥古斯都', '安东尼', '雷必达', '塞克斯图斯·庞培', '马库斯·布鲁图斯', '卡西乌斯'] },
  { y: -43, mo: 12, t: '公敌宣告与西塞罗之死', p: '福尔米埃', m: '今意大利福尔米亚', ll: [13.61, 41.26], k: 'pol', refs: ['阿庇安·内战', '普鲁塔克·西塞罗传'],
    d: '三巨头张贴公敌名单，悬赏杀人，奴隶告发主人可以得到自由，被宣告的人财产充公，用来发军饷。阿庇安说，大约三百名元老与两千名骑士被列入名单，**大多数人逃往西西里，因为那里离意大利近，塞克斯图斯·庞培热情地收留了他们||The greater number, however, went to Sicily because of its nearness to Italy, where Sextus Pompeius received them gladly**。安东尼坚持要西塞罗的命，屋大维争了两天，最后让步。十二月七日，西塞罗在福尔米埃的别墅附近被追上，他把头伸出轿子，**赫伦尼乌斯奉安东尼之命割下他的头，还有他的双手——那双写下“反腓力辞”的手||Herennius cut off his head, by Antony’s command, and his hands—the hands with which he wrote the Philippics**。头和手被钉在罗马广场的讲坛上。',
    who: ['西塞罗', '安东尼', '奥古斯都', '雷必达', '塞克斯图斯·庞培'] },
  { y: -42, mo: 1, t: '神圣的尤利乌斯', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'cul', refs: ['阿庇安·内战', '后世文献'],
    d: '前 42 年元旦，元老院与三巨头宣誓遵守恺撒的一切法令，正式把恺撒列为国家的神，称“神圣的尤利乌斯”，在他火化的地方修建神庙。屋大维从此可以自称“神之子”，这个名号在他后来的宣传里比任何官职都重要。',
    who: ['奥古斯都', '恺撒'], post: ['恺撒'] },
  { y: -42, mo: 10, t: '腓立比之战', p: '腓立比', m: '今希腊东马其顿', ll: [24.29, 41.01], k: 'war', refs: ['普鲁塔克·布鲁图斯传', '普鲁塔克·安东尼传', '阿庇安·内战'],
    d: '布鲁图斯与卡西乌斯在东方搜刮了巨额军费，劫掠了罗得岛与吕西亚，带着十九个军团在马其顿东部的腓立比扎营。普鲁塔克说，渡海前的一个深夜，布鲁图斯在帐中看见一个可怕的身影，问它是谁，**幽灵答道：我是你的恶灵，布鲁图斯，你将在腓立比见到我||Then the phantom answered: I am thy evil genius, Brutus, and thou shalt see me at Philippi**。十月初的第一战，安东尼攻破了卡西乌斯的营地，布鲁图斯却攻下了屋大维的营地，生病的屋大维躲进沼泽才逃过一劫。卡西乌斯误以为布鲁图斯也败了，令奴隶杀死自己。三个星期后的第二战，布鲁图斯战败，第二天也伏剑自尽。共和派最后的军队就此瓦解，安东尼成了战场上的英雄。',
    who: ['马库斯·布鲁图斯', '卡西乌斯', '安东尼', '奥古斯都'] },
  { y: -41, mo: 3, t: '以弗所的“狄俄尼索斯”', p: '以弗所', m: '今土耳其塞尔丘克', ll: [27.34, 37.94], k: 'pol', refs: ['普鲁塔克·安东尼传'],
    d: '腓立比之后，安东尼留在东方筹钱安置老兵，屋大维回意大利分地。安东尼进入以弗所时，**女人扮成酒神的女信徒、男人与少年扮成萨提尔和潘神在前面引路，满城都是常春藤、酒神杖、竖琴和笛子，民众称他为带来欢乐、仁慈的狄俄尼索斯||the people hailing him as Dionysus Giver of Joy and Beneficent**。普鲁塔克接着说，对大多数人来说，他是吃人的、野蛮的狄俄尼索斯：他要亚细亚各城在一年内交出九年的税。',
    who: ['安东尼'] },
  { y: -41, mo: 7, t: '塔尔苏斯的金船', p: '塔尔苏斯', m: '今土耳其梅尔辛省塔尔苏斯', ll: [34.9, 36.92], k: 'dip', refs: ['普鲁塔克·安东尼传'],
    d: '安东尼召埃及女王克娄巴特拉到西里西亚来解释她为何没有援助三巨头。她来了，却是**乘着一艘船尾镀金的游船溯库德诺斯河而上，紫色的帆张开，桨手们用银桨划水||to sail up the river Cydnus in a barge with gilded poop, its sails spread purple, its rowers urging it on with silver oars**，她自己扮成阿佛洛狄忒，斜倚在金线织成的帐篷下，男孩们扮成小爱神为她扇风，岸上的人都跑来看。安东尼请她赴宴，她反请安东尼赴宴，宴会一连四天。这年冬天安东尼随她去了亚历山大里亚。她借安东尼之手处死了妹妹阿尔西诺伊四世。',
    who: ['安东尼', '克娄巴特拉七世'] },
  { y: -40, mo: 2, t: '佩鲁西亚之战', p: '佩鲁西亚', m: '今意大利佩鲁贾', ll: [12.39, 43.11], k: 'war', refs: ['阿庇安·内战', '苏埃托尼乌斯·奥古斯都传'],
    d: '屋大维在意大利没收十八座城市的土地分给老兵，失地的农民涌入罗马。安东尼的妻子富尔维娅与弟弟卢基乌斯·安东尼借此起兵，自称要恢复共和，被阿格里帕与屋大维围在佩鲁西亚。城中饥荒，前 40 年二月卢基乌斯投降。屋大维饶了他，却把城中的议员处死，苏埃托尼乌斯说，**对所有求饶或辩解的人，他只有一句回答：你必须死||making only one reply to all who implored pardon, or endeavoured to excuse themselves, "You must die."**城被烧毁。维吉尔在《牧歌》里写到了失去田地的曼图亚农民，据说他自己的田产也一度被没收。',
    who: ['奥古斯都', '富尔维娅', '卢基乌斯·安东尼', '阿格里帕', '维吉尔'] },
  { y: -40, mo: 3, t: '帕提亚入侵叙利亚', p: '安条克', m: '今土耳其安塔基亚', ll: [36.16, 36.2], k: 'war', refs: ['普鲁塔克·安东尼传', '约瑟夫斯·犹太古史'],
    d: '安东尼还在亚历山大里亚，帕提亚王子帕科鲁斯与投奔帕提亚的罗马人小拉比努斯（恺撒副将拉比努斯之子）趁机入侵，攻下叙利亚、腓尼基与西里西亚，小拉比努斯一直打到卡里亚。帕提亚人扶立哈斯蒙尼家族的玛他提亚·安提柯为犹太国王，帕提亚扶立的新王割掉伯父许尔堪二世的耳朵，使他不能再做大祭司。许尔堪的大臣、以土买人希律逃往罗马。',
    who: ['小拉比努斯', '帕科鲁斯', '玛他提亚·安提柯', '许尔堪二世', '大希律'] },
  { y: -40, mo: 10, t: '布伦迪西乌姆和约', p: '布伦迪西乌姆', m: '今意大利布林迪西', ll: [17.94, 40.64], k: 'dip', refs: ['阿庇安·内战', '普鲁塔克·安东尼传'],
    d: '安东尼带着舰队回到意大利，屋大维的部队在布伦迪西乌姆闭门不纳，两人几乎开战，两边的老兵却不愿再打。富尔维娅恰好死在希腊，双方把一切归罪于她，在布伦迪西乌姆重新划分帝国：以伊利里亚的斯科德拉为界，以西归屋大维，以东归安东尼，阿非利加留给雷必达。为了巩固同盟，安东尼娶了屋大维新寡的姐姐屋大维娅，普鲁塔克说，人们希望**屋大维娅美丽、聪明而端庄||Octavia, who, besides her great beauty, had intelligence and dignity**，能让安东尼回心转意。同年，元老院在安东尼与屋大维的提议下立希律为犹太国王。',
    who: ['安东尼', '奥古斯都', '屋大维娅', '富尔维娅', '雷必达', '大希律'], post: ['富尔维娅'] },
  { y: -39, mo: 3, t: '维吉尔的第四首牧歌', p: '曼图亚', m: '今意大利曼托瓦', ll: [10.79, 45.16], k: 'cul', refs: ['维吉尔', '后世文献'],
    d: '这几年间，维吉尔写成了十首《牧歌》。第四首献给促成布伦迪西乌姆和约的执政官波利奥，预言一个孩子即将降生，黄金时代将随他回到人间，蛇与毒草都会消失。诗人原意大概是安东尼与屋大维娅将要出生的孩子，后来的基督徒却把它读成了基督降生的预言，维吉尔因此在中世纪被尊为“异教的先知”。不久，维吉尔与贺拉斯先后被引荐给屋大维的朋友梅塞纳斯。',
    who: ['维吉尔', '波利奥', '贺拉斯', '梅塞纳斯', '安东尼', '屋大维娅'] },
  { y: -39, mo: 7, t: '米塞努姆和约', p: '米塞努姆', m: '今意大利那不勒斯湾西端', ll: [14.08, 40.78], k: 'dip', refs: ['阿庇安·内战', '普鲁塔克·安东尼传'],
    d: '塞克斯图斯·庞培的舰队封锁海路，罗马闹粮荒，民众在广场上用石头砸屋大维。三巨头只好与他谈判。阿庇安说，**三人在普特奥利的防波堤上会面，堤的两边都是海浪，四周停着护卫的船只||again the three men (Octavius, Antony, and Pompeius) came together on the mole of Puteoli, washed by the waves on both sides, and with ships moored around it as guards**。塞克斯图斯得到西西里、撒丁岛与科西嘉，答应解除封锁、保证粮食供应，逃到他那里的公敌可以回家。签约后他在旗舰上宴请安东尼与屋大维，部将梅诺多鲁斯悄悄建议砍断缆绳，把两人一起扣下，塞克斯图斯说：“你应该先做了再告诉我。”',
    who: ['塞克斯图斯·庞培', '安东尼', '奥古斯都'] },
  { y: -39, mo: 9, t: '文提迪乌斯击退帕提亚', p: '奇里乞亚山口', m: '今土耳其托罗斯山的奇里乞亚门', ll: [34.78, 37.28], k: 'war', refs: ['普鲁塔克·安东尼传', '后世文献'],
    d: '安东尼派老部将文提迪乌斯·巴苏斯东征。文提迪乌斯出身皮凯努姆的平民，少年时曾在同盟者战争后作为俘虏在凯旋式上游街。他在陶鲁斯山口突袭小拉比努斯，又在阿马努斯山击败帕提亚的骑兵，小拉比努斯逃亡途中被擒杀，小亚细亚与西里西亚重归罗马。',
    who: ['文提迪乌斯', '小拉比努斯', '安东尼'] },
  { y: -38, mo: 6, t: '金达洛斯之战', p: '金达洛斯', m: '今叙利亚阿夫林附近', ll: [36.75, 36.4], k: 'war', refs: ['普鲁塔克·安东尼传', '后世文献'],
    d: '帕科鲁斯再度入侵叙利亚，文提迪乌斯故意示弱，引帕提亚骑兵冲上高地，以投石兵与重步兵将其击溃，帕科鲁斯阵亡。这一天据说正是十五年前克拉苏在卡莱战败的日子。普鲁塔克说，这场胜利为克拉苏报了仇，文提迪乌斯是第一个战胜帕提亚人而举行凯旋式的罗马人，安东尼却嫉妒他的功劳，把他召了回去。',
    who: ['文提迪乌斯', '帕科鲁斯', '安东尼'] },
  { y: -37, mo: 7, t: '希律攻陷耶路撒冷 · 安东尼重组东方', p: '耶路撒冷', m: '犹太的都城', ll: [35.23, 31.78], k: 'war', refs: ['约瑟夫斯·犹太古史', '普鲁塔克·安东尼传'],
    d: '希律在罗马将军索西乌斯的帮助下围攻耶路撒冷五个月，夏天破城，罗马士兵屠城，希律花钱才把他们打发走。玛他提亚·安提柯被押到安条克，被安东尼斩首，哈斯蒙尼王朝从此告终。希律娶了哈斯蒙尼家族的公主米利暗，成了罗马扶持的犹太国王。安东尼同时重新安排了东方的附庸国：加拉太交给阿敏塔斯，本都交给波勒蒙，卡帕多西亚交给阿尔凯劳斯，又把西里西亚沿海与腓尼基的一部分送给克娄巴特拉。',
    who: ['大希律', '玛他提亚·安提柯', '安东尼', '阿敏塔斯', '波勒蒙一世', '阿尔凯劳斯', '克娄巴特拉七世'] },
  { y: -36, mo: 9, t: '瑙洛库斯海战 · 雷必达下台', p: '瑙洛库斯', m: '今意大利西西里岛墨西拿以西', ll: [15.27, 38.22], k: 'war', refs: ['阿庇安·内战', '苏埃托尼乌斯·奥古斯都传'],
    d: '米塞努姆和约很快破裂。屋大维的舰队两次被塞克斯图斯与风暴摧毁，他让阿格里帕在库迈附近凿通湖泊建成秘密军港，训练了两万名划桨手，造了装有抓钩弩的新战舰。前 36 年九月三日，阿格里帕在西西里北岸的瑙洛库斯全歼塞克斯图斯的舰队，塞克斯图斯逃往东方，次年在小亚细亚被安东尼的部将处死。雷必达从阿非利加带来十四个军团助战，却想独占西西里，屋大维只带几个随从走进他的军营，士兵们纷纷倒戈。雷必达被剥夺三巨头的权力，只保留大祭司的头衔，在奇尔切伊软禁到死。',
    who: ['阿格里帕', '奥古斯都', '塞克斯图斯·庞培', '雷必达'] },
  { y: -36, mo: 10, t: '安东尼远征帕提亚', p: '弗拉阿斯帕', m: '米底阿特罗帕特尼的王都，今伊朗西阿塞拜疆省，确址未定', ll: [46.6, 37.0], k: 'war', refs: ['普鲁塔克·安东尼传'],
    d: '安东尼集结了十多万人，从亚美尼亚绕道进攻帕提亚的盟国米底阿特罗帕特尼。他急于速战，把攻城器械留在后面，结果攻城车队被帕提亚骑兵全歼，亚美尼亚国王阿尔塔瓦兹德二世也带着骑兵撤走。弗拉阿斯帕久攻不下，冬天将至，安东尼只好在严寒中撤退，二十七天里打了十八仗，损失了约三分之一的军队。克娄巴特拉带着衣服与军饷到腓尼基海边接他。',
    who: ['安东尼', '阿尔塔瓦兹德二世', '弗拉阿特斯四世', '克娄巴特拉七世'] },
  { y: -35, mo: 6, t: '伊利里亚战争', p: '塞斯基亚', m: '今克罗地亚锡萨克', ll: [16.37, 45.48], k: 'war', refs: ['苏埃托尼乌斯·奥古斯都传', '阿庇安·内战'],
    d: '为了证明自己也会打仗，屋大维亲自征讨伊利里亚，前 35 至前 33 年间平定了亚得里亚海东岸的亚波德人、利布尔尼人与达尔马提亚人，攻下潘诺尼亚边上的塞斯基亚。苏埃托尼乌斯说，他在攻城时右膝被石块击伤，又在一座桥倒塌时伤了一条腿和两条胳膊。从达尔马提亚人那里收回的军旗，是三十年前加比尼乌斯丢掉的。屋大维用战利品修建了屋大维娅柱廊与图书馆。',
    who: ['奥古斯都', '阿格里帕', '屋大维娅'] },
  { y: -34, mo: 9, t: '亚历山大里亚的赠礼', p: '亚历山大里亚', m: '今埃及亚历山大', ll: [29.92, 31.2], k: 'pol', refs: ['普鲁塔克·安东尼传'],
    d: '安东尼诱捕了亚美尼亚国王阿尔塔瓦兹德二世，把他用银链锁着带到亚历山大里亚举行凯旋式。随后在体育馆里，他与克娄巴特拉坐在银台上的两张金宝座上，**宣布克娄巴特拉为埃及、塞浦路斯、利比亚与叙利亚洼地的女王，与恺撒里昂共同统治||he declared Cleopatra Queen of Egypt, Cyprus, Libya, and Coele Syria, and she was to share her throne with Caesarion**，把自己与她的儿子们称为“万王之王”，分给他们亚美尼亚、米底、帕提亚与腓尼基、叙利亚、西里西亚，女儿克娄巴特拉·塞勒涅得昔兰尼。罗马人认为他在把罗马的行省送给一个埃及女人。',
    who: ['安东尼', '克娄巴特拉七世', '恺撒里昂', '阿尔塔瓦兹德二世', '克娄巴特拉·塞勒涅'] },
  { y: -32, mo: 10, t: '宣读遗嘱与宣战', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['普鲁塔克·安东尼传', '苏埃托尼乌斯·奥古斯都传'],
    d: '前 33 年底三巨头的任期届满，两位支持安东尼的执政官带着三百名元老逃往东方。安东尼正式休了屋大维娅。屋大维从维斯塔贞女那里强取安东尼的遗嘱，在元老院宣读：安东尼要把克娄巴特拉的子女列为继承人，死后葬在亚历山大里亚。苏埃托尼乌斯说，屋大维借此**让世人知道安东尼已经多么背弃祖国||to make it known to the world how far Antony had degenerated from patriotic feelings**。意大利与西方各行省向屋大维宣誓效忠，罗马向克娄巴特拉宣战，而不是向安东尼。',
    who: ['奥古斯都', '安东尼', '屋大维娅', '克娄巴特拉七世'] },
  { y: -31, mo: 9, t: '亚克兴海战', p: '亚克兴', m: '安布拉基亚湾口，今希腊普雷韦扎附近', ll: [20.75, 38.95], k: 'war', refs: ['普鲁塔克·安东尼传', '苏埃托尼乌斯·奥古斯都传'],
    d: '安东尼与克娄巴特拉的五百艘战舰与大军驻在安布拉基亚湾，阿格里帕先攻占了希腊西岸的港口，切断他们的补给，营中疟疾流行，逃兵不断。九月二日，安东尼的舰队冲出湾口与阿格里帕决战。普鲁塔克说，海战胜负未分时，**克娄巴特拉的六十艘船突然升起帆逃走，从交战的船只中间穿过||suddenly the sixty ships of Cleopatra were seen hoisting their sails for flight and making off through the midst of the combatants**，安东尼丢下还在作战的部下追她而去。被抛弃的舰队战到傍晚才投降，陆军等了七天不见统帅，也降了屋大维。屋大维在战场旁建立“胜利之城”尼科波利斯，在亚克兴重建了阿波罗神庙。',
    who: ['安东尼', '克娄巴特拉七世', '阿格里帕', '奥古斯都'] },
  { y: -30, mo: 8, t: '安东尼与克娄巴特拉之死', p: '亚历山大里亚', m: '今埃及亚历山大', ll: [29.92, 31.2], k: 'war', refs: ['普鲁塔克·安东尼传', '苏埃托尼乌斯·奥古斯都传'],
    d: '屋大维从叙利亚与昔兰尼两路进军埃及。八月一日，安东尼的舰队与骑兵在亚历山大里亚城外倒戈，他听说克娄巴特拉已死，伏剑自尽，被人抬到女王藏身的陵墓里死去。屋大维想把克娄巴特拉活着带回罗马游街，她却设法让人把一条眼镜蛇藏在无花果篮里送进来。罗马士兵冲进去时，她已死在金榻上，侍女伊拉斯死在她脚边，卡尔米昂正在为她扶正王冠，有人怒问：**这事干得漂亮吗，卡尔米昂？她答道：真是漂亮，配得上这么多国王的后裔||A fine deed, this, Charmion! It is indeed most fine, she said, and befitting the descendant of so many kings**，说完倒在榻边。十七岁的恺撒里昂被杀，托勒密王朝灭亡，埃及成为罗马行省，由骑士出身的长官直接向屋大维负责。亚美尼亚的阿尔塔夏斯二世趁机夺回王国。',
    who: ['安东尼', '克娄巴特拉七世', '奥古斯都', '恺撒里昂', '阿尔塔夏斯二世'] },
  { y: -29, mo: 6, t: '克拉苏征服默西亚', p: '默西亚', m: '今保加利亚北部与塞尔维亚东部', ll: [24.5, 43.5], k: 'war', refs: ['后世文献'],
    d: '马其顿总督马库斯·克拉苏（前三头克拉苏之孙）击败越过多瑙河南下的巴斯塔奈人，亲手杀死了他们的国王，又征服了默西亚人。按罗马的旧例，亲手斩杀敌酋的统帅可以把“最高战利品”献给朱庇特，屋大维却以克拉苏没有独立的统帅权为由拒绝了，这一荣誉只能属于他自己。',
    who: ['马库斯·克拉苏', '奥古斯都'] },
  { y: -29, mo: 8, t: '三重凯旋 · 关闭雅努斯神殿', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['奥古斯都·功业录', '苏埃托尼乌斯·奥古斯都传'],
    d: '八月十三日至十五日，屋大维连续三天举行凯旋式，庆祝伊利里亚、亚克兴与埃及的胜利，克娄巴特拉的雕像与她的孩子们在队伍中游街。埃及的财富使罗马的利率一下子降到原来的三分之一。元老院下令关闭雅努斯·奎里努斯神殿的大门，表示全国已无战事，这在罗马历史上只有过两次。《功业录》说：**雅努斯·奎里努斯的神殿，我们的祖先规定，只有在以胜利赢得和平时才关闭||Janus Quirinus, which it was the purpose of our fathers to close when there was peace won by victory**，在我出生前只关闭过两次，在我担任元首时元老院三次下令关闭。',
    who: ['奥古斯都'] },
  { y: -27, mo: 1, t: '“奥古斯都”', p: '罗马元老院', m: '今意大利罗马', ll: [12.485, 41.893], k: 'pol', refs: ['奥古斯都·功业录', '苏埃托尼乌斯·奥古斯都传', '塔西佗·编年史'],
    d: '一月十三日，屋大维在元老院宣布交出全部非常权力，“恢复共和国”。元老们恳求他不要撒手，他才同意接管西班牙、高卢、叙利亚与埃及等驻有军队的行省，为期十年，其余行省交还元老院。三天后，元老院授予他“奥古斯都”的称号，意为“神圣的、可敬的”。《功业录》说：**在我第六、第七次担任执政官时，我结束了内战，在全体一致同意下掌握了一切事务之后，把共和国从我的掌控中交还元老院与罗马人民||In my sixth and seventh consulships, when I had put an end to the civil wars, after having obtained complete control of affairs by universal consent, I transferred the commonwealth from my own dominion to the authority of the senate and Roman people**。塔西佗看得更透：他**用赏赐笼络士兵，用廉价的粮食笼络民众，用安宁的甜头笼络所有人||Augustus won over the soldiers with gifts, the populace with cheap corn, and all men with the sweets of repose**，渐渐把元老院、官员与法律的职能集于一身。他自称“元首”，即首席公民，史家把这一年算作罗马帝国的开始。',
    who: ['奥古斯都', '阿格里帕'] },
  { y: -27, mo: 6, t: '李维的《建城以来史》', p: '帕塔维乌姆', m: '今意大利帕多瓦', ll: [11.88, 45.41], k: 'cul', refs: ['后世文献'],
    d: '帕塔维乌姆人李维在这几年开始写作罗马史，从埃涅阿斯来到意大利写起，一直写到前 9 年德鲁苏斯之死，共一百四十二卷，四十年才写完，今存三十五卷。他在序言里说，罗马已经堕落到既不能忍受自己的恶习、也不能忍受救治的地步，于是要从古人的榜样里寻找教训。奥古斯都称他为“庞培派”，却并不妨碍两人的友谊，还请他指导少年克劳狄乌斯写史。',
    who: ['李维', '奥古斯都'] },
  { y: -26, mo: 6, t: '坎塔布里亚战争', p: '坎塔布里亚', m: '今西班牙坎塔布里亚与阿斯图里亚斯', ll: [-4.0, 43.1], k: 'war', refs: ['苏埃托尼乌斯·奥古斯都传', '后世文献'],
    d: '伊比利亚半岛西北的坎塔布里人与阿斯图里人仍未臣服，经常下山劫掠。奥古斯都亲自带七个军团进山，这是他亲征的最后一场战争。山地游击战旷日持久，他自己病倒在塔拉科，由部将继续作战。罗马人在战后为退伍老兵建立了埃梅里塔·奥古斯塔（今梅里达）与凯撒奥古斯塔（今萨拉戈萨）。',
    who: ['奥古斯都', '阿格里帕'] },
  { y: -25, mo: 6, t: '加拉太行省 · 尤巴二世', p: '凯撒里亚（毛里塔尼亚）', m: '今阿尔及利亚舍尔沙勒', ll: [2.2, 36.6], k: 'pol', refs: ['后世文献'],
    d: '加拉太国王阿敏塔斯在征讨托罗斯山区的部落时被杀，奥古斯都没有另立国王，把加拉太、吕考尼亚与皮西迪亚改为加拉太行省。同年，他把毛里塔尼亚交给努米底亚末王尤巴一世之子尤巴二世，尤巴从小在罗马长大，在屋大维娅家中受教育，娶了克娄巴特拉与安东尼的女儿克娄巴特拉·塞勒涅。他以约尔为都城，改名凯撒里亚，是古代最博学的国王之一，用希腊文写过罗马史、阿拉伯志与戏剧史。',
    who: ['阿敏塔斯', '尤巴二世', '克娄巴特拉·塞勒涅', '奥古斯都', '屋大维娅'] },
  { y: -25, mo: 9, t: '阿拉伯远征', p: '马里巴', m: '赛伯伊王国的都城，今也门马里卜', ll: [45.33, 15.43], k: 'war', refs: ['后世文献'],
    d: '奥古斯都听说南阿拉伯富产香料，命埃及长官埃利乌斯·加卢斯带一万人远征。纳巴泰国王派大臣西莱乌斯做向导，他把罗马军队领进荒漠绕了半年，士兵死于疾病与干渴者无数。加卢斯打到赛伯伊人的都城马里巴，围了六天因缺水而撤，归途只用了两个多月。地理学家斯特拉波是加卢斯的朋友，记下了这次失败。',
    who: ['奥古斯都'] },
  { y: -23, mo: 7, t: '第二次权力安排', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['苏埃托尼乌斯·奥古斯都传', '后世文献'],
    d: '这年春天奥古斯都病得几乎要死，把指环交给阿格里帕，人们以为他选定了继承人。病愈后，他辞去连任八年的执政官，改由元老院授予终身的保民官权力与高于一切行省总督的统帅权，从此不再需要每年竞选。秋天，他的外甥兼女婿、十九岁的小马塞卢斯病死，维吉尔在《埃涅阿斯纪》第六卷里为他写下了挽歌，据说屋大维娅听诗人朗诵时当场昏厥。',
    who: ['奥古斯都', '阿格里帕', '小马塞卢斯', '维吉尔', '屋大维娅'] },
  { y: -20, mo: 5, t: '帕提亚归还军旗', p: '幼发拉底河', m: '今叙利亚与伊拉克边境一带', ll: [40.2, 35.0], k: 'dip', refs: ['奥古斯都·功业录', '苏埃托尼乌斯·奥古斯都传'],
    d: '奥古斯都亲赴东方，提比略带兵进入亚美尼亚，扶立亲罗马的提格兰三世。帕提亚国王弗拉阿特斯四世内有王位争夺，不愿开战，交还了克拉苏在卡莱与安东尼在米底丢失的军旗和俘虏。这是外交而非战争的成果，奥古斯都却把它宣传成最大的胜利，《功业录》说：**我迫使帕提亚人把三支罗马军队的战利品与军旗交还给我，并且作为求情者来寻求罗马人民的友谊||I have compelled the Parthians to give up to me the spoils and standards of three Roman armies, and as suppliants to seek the friendship of the Roman people**。著名的“第一门”奥古斯都雕像胸甲上刻的就是帕提亚人献还军旗的场面。',
    who: ['奥古斯都', '提比略', '弗拉阿特斯四世'] },
  { y: -20, mo: 9, t: '希律重建圣殿', p: '耶路撒冷', m: '犹太的都城', ll: [35.235, 31.778], k: 'cul', refs: ['约瑟夫斯·犹太古史'],
    d: '大希律以残忍著称，处死了妻子米利暗和她的家人，却也是古代最大的建造者之一：他在斯特拉托塔修建了人工海港凯撒里亚，在死海边修了马萨达要塞，在耶路撒冷建了以安东尼命名的安东尼亚塔。约瑟夫斯说，**希律在他统治的第十八年，着手一项极大的工程，自己出资重建上帝的圣殿，扩大它的范围，把它加高到极为壮观的高度||Herod, in the eighteenth year of his reign, and after the acts already mentioned, undertook a very great work, that is, to build of himself the temple of God, and make it larger in compass, and to raise it to a most magnificent altitude**。工程持续了八十多年，公元 70 年被罗马人焚毁，今天耶路撒冷的“哭墙”就是它的西墙。',
    who: ['大希律'] },
  { y: -19, mo: 6, t: '坎塔布里人被征服', p: '坎塔布里亚', m: '今西班牙坎塔布里亚', ll: [-4.0, 43.1], k: 'war', refs: ['后世文献'],
    d: '坎塔布里亚的战事断断续续打了七年，被卖为奴隶的坎塔布里人杀死主人逃回山中再次起事。阿格里帕亲自前来，用强攻和屠杀结束了战争，把幸存的山民迁到平原居住。罗马从前 218 年踏上伊比利亚半岛，到这时才用了两百年征服整个半岛。',
    who: ['阿格里帕'] },
  { y: -19, mo: 9, t: '维吉尔之死', p: '布伦迪西乌姆', m: '今意大利布林迪西', ll: [17.94, 40.64], k: 'cul', refs: ['维吉尔', '后世文献'],
    d: '维吉尔花了十一年写《埃涅阿斯纪》，开篇是：**我歌唱战争和那个人，他第一个从特洛伊的海岸被命运驱赶着流亡到意大利||Arms and the man I sing, who first made way, predestined exile, from the Trojan shore to Italy**。他把罗马的起源追溯到特洛伊王子埃涅阿斯，也就是尤利乌斯家族的祖先，在第六卷里让冥界中的安基塞斯预言罗马的使命：罗马人啊，**要学会以至高的权力统治万国，你的技艺是让世界保持持久的和平，宽恕降服者，打倒骄傲者||learn with sovereign sway To rule the nations. Thy great art shall be To keep the world in lasting peace, to spare humbled foe, and crush to earth the proud**。他去希腊游历，在墨伽拉中暑，回到布伦迪西乌姆就死了，遗嘱要烧掉尚未修订完的史诗，奥古斯都下令保留并出版。',
    who: ['维吉尔', '奥古斯都'] },
  { y: -18, mo: 6, t: '婚姻法', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['苏埃托尼乌斯·奥古斯都传', '后世文献'],
    d: '奥古斯都认为罗马上层的衰落在于道德败坏与不愿生育，通过了《尤利乌斯婚姻法》与《尤利乌斯通奸法》：未婚与无子的男女不能继承遗产，生满三个孩子的人享有特权，通奸成为国家处罚的罪行。苏埃托尼乌斯说，多年后骑士们在剧场里大声要求废除这些法律，他便把日耳曼尼库斯的孩子们抱在怀里给他们看，劝他们效法。这些法律后来恰恰用在了他自己的女儿身上。',
    who: ['奥古斯都'] },
  { y: -17, mo: 6, t: '世纪庆典', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'cul', refs: ['贺拉斯', '后世文献'],
    d: '奥古斯都依据西卜林神谕举办“世纪庆典”，宣告一个新时代的开始。六月初的三天三夜里，奥古斯都与阿格里帕向命运女神、生育女神与大地母神献祭，二十七名少男与二十七名少女在帕拉丁山的阿波罗神庙前合唱贺拉斯写的《世纪之歌》：**阿波罗，森林的女主人狄安娜||Phoebe silvarumque potens Diana**……贺拉斯是解放奴隶之子，曾在腓立比随布鲁图斯作战，后被梅塞纳斯收入门下，他的《颂歌》里有“及时行乐”（carpe diem）与“为祖国而死是甜美而光荣的”这样的名句；亚克兴之后他写道：**现在该喝酒了||Nunc est bibendum**。',
    who: ['贺拉斯', '奥古斯都', '阿格里帕', '梅塞纳斯'] },
  { y: -15, mo: 8, t: '征服雷蒂亚与诺里库姆', p: '雷蒂亚', m: '今瑞士东部、奥地利西部与德国南部', ll: [10.5, 47.3], k: 'war', refs: ['苏埃托尼乌斯·奥古斯都传', '贺拉斯', '后世文献'],
    d: '奥古斯都的两个继子分兵夹击阿尔卑斯山区：德鲁苏斯从意大利北上翻越布伦纳山口，提比略从高卢东进，在博登湖上用船队击败文德利奇人，八月一日两军会师，雷蒂亚、文德利奇亚与诺里库姆全部并入帝国，帝国的边界推到了多瑙河上游。今天的奥格斯堡与特里尔都是在这几年建立的。贺拉斯在《颂歌》第四卷里为兄弟二人写了凯歌。法国南部拉蒂尔比的“阿尔卑斯凯旋碑”刻着被征服的四十五个部落的名字。',
    who: ['提比略', '老德鲁苏斯', '奥古斯都', '贺拉斯'] },
  { y: -13, mo: 7, t: '和平祭坛', p: '马尔斯校场', m: '今意大利罗马', ll: [12.476, 41.906], k: 'cul', refs: ['奥古斯都·功业录'],
    d: '奥古斯都在西班牙与高卢住了三年，回到罗马时，元老院决定为他修建一座和平祭坛。《功业录》说：**元老院议决在马尔斯校场为奥古斯都的和平奉献一座祭坛，命官员、祭司与维斯塔贞女每年在这一天献祭||the senate voted that in honor of my return an altar of the Augustan Peace should be consecrated in the Campus Martius, and upon this altar it ordered the magistrates and priests and vestal virgins to offer sacrifices on each anniversary**。祭坛四年后落成，围墙上的浮雕刻着奥古斯都、阿格里帕、莉薇娅与皇室子孙排成游行队伍的样子，是奥古斯都时代艺术最好的代表，今天还能在罗马看到。“奥古斯都治下的和平”此后被称为“罗马和平”。',
    who: ['奥古斯都', '阿格里帕', '莉薇娅'] },
  { y: -12, mo: 3, t: '阿格里帕之死 · 奥古斯都任大祭司', p: '坎帕尼亚', m: '今意大利那不勒斯一带', ll: [14.3, 40.9], k: 'pol', refs: ['苏埃托尼乌斯·奥古斯都传', '后世文献'],
    d: '三月初，被软禁了二十多年的雷必达死后，奥古斯都当选大祭司，从此每一位皇帝都兼任这个职位，后来的教皇也沿用了“大祭司”的称号。同月，从潘诺尼亚回来的阿格里帕在坎帕尼亚病死，年约五十一岁。他替奥古斯都打赢了瑙洛库斯与亚克兴，修建了罗马的万神殿、第一座大型公共浴场和两条引水渠，绘制了全帝国的地图。奥古斯都让女儿大尤利娅与他结婚，生下盖乌斯、卢基乌斯两个外孙，被奥古斯都收为养子。阿格里帕死后，奥古斯都逼提比略与爱妻离婚，娶了寡居的尤利娅。',
    who: ['阿格里帕', '奥古斯都', '雷必达', '大尤利娅', '提比略', '盖乌斯·恺撒', '卢基乌斯·恺撒'], post: ['雷必达'] },
  { y: -11, mo: 6, t: '征服潘诺尼亚', p: '潘诺尼亚', m: '今匈牙利西部与克罗地亚北部', ll: [17.5, 46.0], k: 'war', refs: ['苏埃托尼乌斯·提比略传', '后世文献'],
    d: '阿格里帕死后，潘诺尼亚人起事，提比略接替他征讨，从前 12 年到前 9 年连年作战，把萨瓦河与德拉瓦河流域并入伊利里库姆，帝国在中欧的边界推到了多瑙河中游。他把被俘的青壮年卖到外地为奴，这些人二十年后成了大起义的火种。',
    who: ['提比略', '阿格里帕'], post: ['阿格里帕'] },
  { y: -9, mo: 9, t: '德鲁苏斯之死', p: '易北河', m: '今德国萨勒河与易北河一带', ll: [11.8, 51.9], k: 'war', refs: ['苏埃托尼乌斯·奥古斯都传', '后世文献'],
    d: '德鲁苏斯从前 12 年起四次渡过莱茵河进攻日耳曼人，开凿运河让舰队从莱茵河驶进北海，征服了弗里西人，深入卡蒂人与切鲁西人的土地，前 9 年打到易北河边。据说一个身形高大的蛮族女人在河边拦住他，用拉丁语说：“贪得无厌的德鲁苏斯，你要去哪里？命运不许你看到这片土地。你的生命已经到了尽头。”回程中他从马上摔下，伤口感染，三十天后死去，年仅二十九岁。提比略连夜赶了三百多公里来见他最后一面，步行护送灵柩回罗马。莱茵河与易北河之间的日耳曼人名义上归服了罗马。同时，马科曼尼人在国王马罗博杜乌斯率领下避开罗马，迁到波希米亚，建立了日耳曼人的第一个大王国。',
    who: ['老德鲁苏斯', '提比略', '马罗博杜乌斯'] },
  { y: -6, mo: 6, t: '提比略退隐罗得岛', p: '罗得', m: '今希腊罗得岛', ll: [28.22, 36.44], k: 'pol', refs: ['苏埃托尼乌斯·提比略传'],
    d: '提比略刚刚获得五年的保民官权力，却突然请求退隐。他与大尤利娅的婚姻很不幸，奥古斯都又明显偏爱两个外孙，十四岁的盖乌斯已被民众提名为执政官。提比略不顾母亲莉薇娅的恳求，绝食四天，终于获准离开，到罗得岛去做一个普通人，苏埃托尼乌斯说，**他满足于一座小房子和城外一座不大的别墅，过着完全私人的生活||Here contenting himself with a small house, and a villa not much larger, near the town, he led entirely a private life**，去学园听哲学家讲课。他在那里住了七年多。',
    who: ['提比略', '莉薇娅', '大尤利娅', '盖乌斯·恺撒', '奥古斯都'] },
  { y: -5, mo: 12, t: '耶稣诞生', p: '伯利恒', m: '今巴勒斯坦伯利恒', ll: [35.2, 31.7], k: 'cul', refs: ['新约'],
    d: '据《马太福音》，**希律王的时候，耶稣生在犹太的伯利恒||Now when Jesus was born in Bethlehem of Judaea in the days of Herod the king**，东方的博士来朝拜“犹太人的王”，希律恐慌，下令杀死伯利恒两岁以下的男孩，约瑟带着马利亚与婴孩逃往埃及。六世纪的修士狄奥尼修斯推算耶稣生于罗马建城 754 年，定为公元元年，但希律死于前 4 年，今天的学者一般认为耶稣生于前 6 至前 4 年之间，生日也已无从考证。',
    who: ['耶稣', '大希律'] },
  { y: -4, mo: 3, t: '大希律之死', p: '耶利哥', m: '今巴勒斯坦耶利哥', ll: [35.44, 31.86], k: 'pol', refs: ['约瑟夫斯·犹太古史'],
    d: '希律晚年病重，又接连处死了三个儿子，奥古斯都据说曾开玩笑说：“做希律的猪也比做他的儿子好。”他在圣殿大门上挂了一只金鹰，律法学者的学生们把它砍了下来，希律把他们活活烧死。他死在耶利哥的冬宫，约瑟夫斯说，**这个人对所有人一样残暴，是自己激情的奴隶，置是非于不顾，却又像任何人一样受到命运的眷顾||A man he was of great barbarity towards all men equally, and a slave to his passion; but above the consideration of what was right; yet was he favored by fortune as much as any man ever was**。奥古斯都把王国分给他的三个儿子：亚基老得犹太、撒玛利亚与以土买，希律·安提帕得加利利与佩利亚，腓力得东北的特拉可尼。希律诸子的分封地都不再称王。',
    who: ['大希律', '亚基老', '希律·安提帕', '奥古斯都'] },
  { y: -2, mo: 2, t: '“国父” · 尤利娅被流放', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['奥古斯都·功业录', '苏埃托尼乌斯·奥古斯都传'],
    d: '二月五日，元老院、骑士与全体罗马人民授予奥古斯都“国父”的称号。《功业录》说：**在我第十三次担任执政官时，元老院、骑士阶层与全体罗马人民授予我“祖国之父”的称号||While I was consul for the thirteenth time the senate and the equestrian order and the entire Roman people gave me the title of father of the fatherland**。同年八月，他落成了奥古斯都广场与复仇者马尔斯神庙。也就在这一年，他得知女儿大尤利娅私通多名贵族青年，其中有安东尼与富尔维娅的儿子尤卢斯·安东尼，盛怒之下按自己的通奸法把她流放到潘达塔里亚岛，终身不许她回罗马。',
    who: ['奥古斯都', '大尤利娅'] },
  { y: 4, mo: 6, t: '收养提比略', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['苏埃托尼乌斯·提比略传', '苏埃托尼乌斯·奥古斯都传'],
    d: '奥古斯都的两个外孙兼养子先后死去：卢基乌斯在公元 2 年死于马西利亚，盖乌斯在亚美尼亚的围城战中受伤，公元 4 年死在吕西亚。六十六岁的奥古斯都只剩下一个选择，六月二十六日收养了从罗得岛回来的提比略，同时让提比略收养侄子日耳曼尼库斯。苏埃托尼乌斯说，奥古斯都在民众大会上发誓，**他收养提比略是为了公共的利益||he adopted him for the public good**，有人觉得这句话里带着几分无奈。',
    who: ['奥古斯都', '提比略', '盖乌斯·恺撒', '卢基乌斯·恺撒', '日耳曼尼库斯'], post: ['盖乌斯·恺撒', '卢基乌斯·恺撒'] },
  { y: 6, mo: 3, t: '犹太行省与居里扭的人口登记', p: '耶路撒冷', m: '犹太的都城', ll: [35.23, 31.78], k: 'pol', refs: ['约瑟夫斯·犹太古史', '新约'],
    d: '亚基老统治残暴，犹太人与撒玛利亚人联名向奥古斯都控告，奥古斯都把他流放到高卢的维埃纳。约瑟夫斯说，**于是亚基老的领地被并入叙利亚行省，曾任执政官的居里扭被凯撒派到叙利亚清点人民的财产||So Archelaus’s country was laid to the province of Syria; and Cyrenius, one that had been consul, was sent by Caesar to take account of people’s effects in Syria**。犹太由一名骑士出身的长官驻守凯撒里亚管理，二十年后的长官是本丢·彼拉多。这次登记激起了加利利人犹大的起义，他号召犹太人除上帝外不认任何主人。《路加福音》把耶稣的降生与这次登记联系在一起：**那时，凯撒奥古斯都有旨意下来，叫天下人民都报名上册||there went out a decree from Caesar Augustus, that all the world should be taxed**。',
    who: ['亚基老', '奥古斯都', '耶稣'] },
  { y: 6, mo: 6, t: '潘诺尼亚大起义', p: '达尔马提亚', m: '今波黑与克罗地亚', ll: [17.6, 44.0], k: 'war', refs: ['苏埃托尼乌斯·提比略传', '后世文献'],
    d: '提比略正带着十二个军团从多瑙河与莱茵河两路夹攻马罗博杜乌斯，伊利里库姆的达尔马提亚人与潘诺尼亚人突然起事，两个都叫巴托的首领率二十万人杀死罗马商人与驻军，罗马城一度担心他们十天之内就会兵临意大利。提比略只好与马罗博杜乌斯议和，回师平叛。苏埃托尼乌斯说，这是**自迦太基战争以来最严重的一场对外战争||the most serious of all the foreign wars since the Carthaginian**，提比略以十五个军团与同样多的辅助部队打了三年。奥古斯都在意大利重新征兵，甚至把解放奴隶编入军队。',
    who: ['提比略', '马罗博杜乌斯', '奥古斯都', '日耳曼尼库斯'] },
  { y: 8, mo: 11, t: '奥维德被流放', p: '托弥', m: '黑海西岸的希腊城市，今罗马尼亚康斯坦察', ll: [28.65, 44.18], k: 'cul', refs: ['奥维德', '后世文献'],
    d: '罗马最受欢迎的诗人奥维德被奥古斯都一纸命令流放到黑海边的托弥，罪名据他自己说是“一首诗和一个错误”：诗是教人调情的《爱的艺术》，错误他始终不肯说，可能牵涉到同年被流放的奥古斯都外孙女小尤利娅。他在边城里写哀诗乞求赦免，直到死也没能回来。他刚刚写完十五卷的《变形记》，结尾说：**我已完成一部巨著，无论朱庇特的愤怒、火与刀剑，还是吞噬一切的时间，都不能把它毁灭||And now, I have completed a great work, which not Jove\'s anger, and not fire nor steel, nor fast-consuming time can sweep away**。',
    who: ['奥维德', '奥古斯都'] },
  { y: 9, mo: 8, t: '大起义平定', p: '安德特里乌姆', m: '今克罗地亚斯普利特附近', ll: [16.55, 43.6], k: 'war', refs: ['苏埃托尼乌斯·提比略传', '后世文献'],
    d: '提比略以围困与焦土战术逐个山谷地清剿，潘诺尼亚的巴托先投降，又被达尔马提亚的巴托处死。公元 9 年夏天，提比略与日耳曼尼库斯攻下达尔马提亚人最后的据点安德特里乌姆，起义的最后一位首领出城投降。被问到为何造反时，他说：“是你们罗马人造成的，你们派来看守羊群的不是牧人和狗，而是狼。”提比略被授予凯旋式。',
    who: ['提比略', '日耳曼尼库斯'] },
  { y: 9, mo: 9, t: '条顿堡森林', p: '卡尔克里泽', m: '今德国下萨克森州奥斯纳布吕克以北', ll: [8.13, 52.41], k: 'war', refs: ['苏埃托尼乌斯·奥古斯都传', '塔西佗·编年史', '考古'],
    d: '日耳曼总督瓦卢斯把莱茵河以东当成已经驯服的行省，在那里审案、征税。他信任的切鲁西人首领阿米尼乌斯曾在罗马军中服役、获得骑士身份，暗中联络各部，九月诱使瓦卢斯带着三个军团离开夏营去平定一场“叛乱”。罗马军队在条顿堡森林的泥沼与山林间被伏击三天，第十七、十八、十九军团约两万人全军覆没，瓦卢斯自杀。1987 年起在卡尔克里泽出土的武器与遗骨证实了战场的位置。消息传到罗马，苏埃托尼乌斯说奥古斯都几个月不剃须发，**有时用头撞门框，喊道：昆克提利乌斯·瓦卢斯，还我军团||sometimes knocked his head against the door-post, crying out, "O, Quintilius Varus! give me back my legions!"**这三个军团的番号此后再也没有使用过。莱茵河以东的土地全部丢失，罗马从此以莱茵河为界。',
    who: ['瓦卢斯', '阿米尼乌斯', '奥古斯都'] },
  { y: 14, mo: 8, t: '奥古斯都之死', p: '诺拉', m: '今意大利诺拉', ll: [14.53, 40.93], k: 'pol', refs: ['苏埃托尼乌斯·奥古斯都传', '塔西佗·编年史', '奥古斯都·功业录'],
    d: '奥古斯都送提比略去伊利里库姆，回程中在诺拉病倒，那是他父亲去世的地方。苏埃托尼乌斯说，他在临终那天要来镜子，让人梳好头发，问进来的朋友们：**你们觉得我把人生这出戏演好了吗？||Do you think that I have acted my part on the stage of life well?**又念了一句喜剧收场时的台词，请大家鼓掌。他在莉薇娅的怀里死去，最后一句话是：**莉薇娅！记着我们的婚姻，永别了！||Livia ! live mindful of our union; and now, farewell!**那天是八月十九日，离他七十六岁生日还差一个多月。他曾**自豪地说，他接手的罗马是砖砌的，留下的是大理石的||he boasted, not without reason, that he "found it of brick, but left it of marble."**元老院把他列为神，他亲笔写的《功业录》被刻在他的陵墓前的铜柱上，抄本刻在各行省的神庙里，安卡拉的一份保存至今。提比略顺理成章地继承了一切，塔西佗在《编年史》的开头说，到这时，**还有几个人亲眼见过共和国呢？||How few were left who had seen the republic!**',
    who: ['奥古斯都', '莉薇娅', '提比略'] },
];

// 人物：[姓名, 势力, 原名, 生卒, 简介]；只写势力的条目，原名、生卒与简介取自合集的跨卷人物（_people.js）
const PEOPLE_RAW = [
  ['奥古斯都', 'octavian', 'Gaius Octavius → Imperator Caesar Divi filius Augustus', '前63–公元14', '恺撒姐姐的外孙，四岁丧父，十八岁时被恺撒的遗嘱收为养子，改名盖乌斯·尤利乌斯·恺撒，后人称他屋大维。先联合元老院打击安东尼，又与安东尼、雷必达结成后三头，在腓立比击败刺杀恺撒的共和派，在瑙洛库斯与亚克兴相继除掉塞克斯图斯·庞培与安东尼。前 27 年获“奥古斯都”称号，以“元首”的名义统治罗马四十一年，保留共和国的外壳而集军权、保民官权与宗教权于一身，开创了罗马帝国。他体弱多病，身边离不开阿格里帕与梅塞纳斯，晚年接连失去继承人，最终把帝国交给继子提比略。'],
  ['安东尼', 'antony', '', '', ''],
  ['雷必达', 'lepidus', '', '', ''],
  ['阿格里帕', 'octavian', 'Marcus Vipsanius Agrippa', '约前63–前12', '出身寒微，屋大维少年时的同学与终生的挚友。屋大维的几乎每一场大胜都出自他手：佩鲁西亚、瑙洛库斯、亚克兴与坎塔布里亚。三次任执政官，曾以营造官的身份整修罗马的下水道与引水渠，修建了最早的万神殿与公共浴场，主持绘制帝国全图。前 21 年娶奥古斯都的女儿尤利娅，生下盖乌斯、卢基乌斯、小阿格里皮娜等五个孩子，后来的皇帝卡利古拉与尼禄都是他的后人。'],
  ['梅塞纳斯', 'octavian', 'Gaius Cilnius Maecenas', '约前70–前8', '埃特鲁里亚王族的后裔，骑士，屋大维早年最亲信的谋士，屋大维出征时常由他坐镇罗马与意大利，替屋大维谈成了布伦迪西乌姆与塔兰托的协议。他本人不肯担任任何官职，以奢华与文雅著称，把维吉尔、贺拉斯、普罗佩提乌斯招到身边，他的名字后来在欧洲语言里成了“文艺赞助人”的代称。'],
  ['屋大维娅', 'octavian', 'Octavia Minor', '约前69–前11', '屋大维的同父姐姐，以美貌与贤德著称。前 40 年丧夫后嫁给安东尼，为他生下两个女儿，多次在丈夫与弟弟之间斡旋，前 32 年被安东尼休弃，仍抚养安东尼与前妻富尔维娅、甚至与克娄巴特拉所生的孩子。儿子小马塞卢斯早逝，她从此闭门不出。'],
  ['莉薇娅', 'octavian', 'Livia Drusilla', '前58–公元29', '克劳狄家族的贵族女子，十六岁嫁给提比略·克劳狄·尼禄，生下提比略。前 38 年怀着次子德鲁苏斯时被屋大维看中，与前夫离婚，嫁给屋大维，两人结婚五十一年，没有共同的孩子。她精明谨慎，是奥古斯都最亲近的顾问，被后世怀疑为让儿子继位而害死了奥古斯都的其他继承人。奥古斯都在遗嘱中把她收为养女，赐名尤利娅·奥古斯塔。'],
  ['提比略', 'octavian', 'Tiberius Claudius Nero', '前42–公元37', '莉薇娅与前夫之子，奥古斯都的继子，罗马第二位皇帝。少年从军，前 20 年从帕提亚手中取回军旗，又征服雷蒂亚、潘诺尼亚，平定伊利里库姆大起义，在日耳曼收拾瓦卢斯战败后的残局，是当时最出色的将领。被迫与爱妻维普萨尼娅离婚、娶尤利娅后，自请退隐罗得岛七年，公元 4 年才被奥古斯都收养，公元 14 年继位。'],
  ['老德鲁苏斯', 'octavian', 'Nero Claudius Drusus', '前38–前9', '莉薇娅的次子，提比略之弟，在母亲嫁给屋大维三个月后出生。与哥哥一同征服阿尔卑斯山区，此后四次进军日耳曼，开凿运河通往北海，前 9 年打到易北河，回程坠马而死，元老院追赠他与子孙“日耳曼尼库斯”的称号。他的儿子是日耳曼尼库斯与后来的皇帝克劳狄乌斯。'],
  ['大尤利娅', 'octavian', 'Julia Caesaris filia', '前39–公元14', '奥古斯都唯一的孩子，母亲是他的第二个妻子斯克里博尼娅，出生当天父母就离了婚。父亲把她当作安排继承的工具，先后嫁给表兄小马塞卢斯、阿格里帕与提比略。前 2 年被控与多名贵族通奸，被父亲流放到潘达塔里亚岛，后移居雷焦，奥古斯都至死不肯原谅她，她在父亲死后几个月去世。'],
  ['盖乌斯·恺撒', 'octavian', 'Gaius Julius Caesar Vipsanianus', '前20–公元4', '阿格里帕与尤利娅的长子，三岁被外祖父奥古斯都收为养子，十四岁被提名为执政官，号称“青年元首”，被视为帝国的继承人。公元 1 年奉命巡视东方，与帕提亚国王在幼发拉底河的岛上会盟，在亚美尼亚的围城战中受伤，归途中死在吕西亚。'],
  ['卢基乌斯·恺撒', 'octavian', 'Lucius Julius Caesar Vipsanianus', '前17–公元2', '阿格里帕与尤利娅的次子，与哥哥盖乌斯一同被奥古斯都收为养子，同样获得“青年元首”的称号。公元 2 年奉命前往西班牙的军中，途经马西利亚时病死。'],
  ['小马塞卢斯', 'octavian', 'Marcus Claudius Marcellus', '前42–前23', '屋大维娅与前夫之子，奥古斯都的外甥。前 25 年娶了表妹尤利娅，被视为舅舅属意的继承人，与阿格里帕暗中不和。前 23 年任营造官时病死，是第一个葬入奥古斯都陵墓的人，维吉尔在《埃涅阿斯纪》第六卷末为他写了挽诗，罗马的马塞卢斯剧场以他命名。'],
  ['日耳曼尼库斯', 'octavian', 'Germanicus Julius Caesar', '前15–公元19', '老德鲁苏斯之子，奥古斯都的外甥孙，公元 4 年被伯父提比略收养。随提比略平定伊利里库姆大起义，公元 14 年起统率莱茵河的八个军团，深受军队与民众爱戴，娶了阿格里帕的女儿阿格里皮娜，皇帝卡利古拉是他的儿子。'],
  ['西塞罗', 'rome', '', '', ''],
  ['恺撒', 'rome', '', '', ''],
  ['马库斯·克拉苏', 'rome', 'Marcus Licinius Crassus', '?–?', '前三头克拉苏的孙子，起初追随塞克斯图斯·庞培与安东尼，后投靠屋大维，前 30 年与屋大维同任执政官。任马其顿总督时征服默西亚，击败巴斯塔奈人，亲手杀死其王，却没能获准献上“最高战利品”，此后再无记载。'],
  ['波利奥', 'rome', 'Gaius Asinius Pollio', '前75–公元4', '恺撒的部将，曾随恺撒渡过卢比孔河，恺撒死后任远西班牙总督，倒向安东尼。前 40 年任执政官，促成布伦迪西乌姆和约，次年征服帕提尼人后退出政坛，建立了罗马第一座公共图书馆。他写过一部内战史，是维吉尔与贺拉斯早年的赞助人。'],
  ['维吉尔', 'rome', 'Publius Vergilius Maro', '前70–前19', '曼图亚附近的农家子弟，罗马最伟大的诗人。先写《牧歌》十首，又在梅塞纳斯的鼓励下写《农事诗》四卷，最后用十一年写《埃涅阿斯纪》，讲特洛伊王子埃涅阿斯流亡意大利、成为罗马人祖先的故事，把罗马的命运写成神意。诗未改定就病死于布伦迪西乌姆，奥古斯都违背他的遗愿下令出版。在中世纪被视为预言基督的先知，但丁让他做《神曲》中游历地狱与炼狱的向导。'],
  ['贺拉斯', 'rome', 'Quintus Horatius Flaccus', '前65–前8', '阿普利亚的韦努西亚人，解放奴隶之子，父亲倾尽家财送他到罗马与雅典求学。腓立比之战时在布鲁图斯军中任军团长官，战败后家产被没收，做了书记员。经维吉尔引荐成为梅塞纳斯的门客，得到萨宾山中的一座农庄。写有《讽刺诗》《长短句》《颂歌》《书信集》与《诗艺》，“及时行乐”“为祖国而死是甜美而光荣的”都出自他的《颂歌》，前 17 年为世纪庆典写了《世纪之歌》。'],
  ['李维', 'rome', 'Titus Livius', '前59–公元17', '帕塔维乌姆（今帕多瓦）人，没有担任过官职，也没有从过军，毕生在罗马写作罗马史。《建城以来史》一百四十二卷，从罗马建城写到前 9 年，今存第一至十卷与第二十一至四十五卷，罗马早期的传说与汉尼拔战争主要靠他流传下来。'],
  ['奥维德', 'rome', 'Publius Ovidius Naso', '前43–公元17', '苏尔莫的骑士之子，放弃仕途专心写诗，以《恋歌》《爱的艺术》《女杰书简》风靡罗马。他的《变形记》十五卷把两百多个希腊罗马神话串成一部从开天辟地到恺撒成神的长诗，是后世欧洲文学与绘画取材最多的古典作品。公元 8 年被奥古斯都流放到黑海边的托弥，原因至今是谜，在那里写了《哀怨集》与《黑海书简》，死于流放地。'],
  ['瓦卢斯', 'rome', 'Publius Quinctilius Varus', '前46–公元9', '没落的贵族世家出身，娶了阿格里帕的女儿，是奥古斯都家族的姻亲。前 13 年与提比略同任执政官，后任阿非利加与叙利亚总督，希律死后镇压犹太人起事，钉死了两千人。公元 7 年调任日耳曼总督，把那里当作已经平定的行省治理，公元 9 年在条顿堡森林中伏，三个军团全军覆没，他自杀。'],
  ['富尔维娅', 'antony', 'Fulvia', '?–前40', '罗马最有权势的女人之一，先后嫁给平民派领袖克洛迪乌斯、恺撒的支持者库里奥和安东尼。丈夫远在东方时，她与小叔卢基乌斯·安东尼在意大利起兵反对屋大维，佩鲁西亚失败后逃到希腊，在西库翁病死。据说西塞罗的头被送来时，她用发簪刺穿了他的舌头。'],
  ['卢基乌斯·安东尼', 'antony', 'Lucius Antonius', '?–?', '安东尼的幼弟，前 41 年任执政官，与嫂嫂富尔维娅借老兵安置引起的不满发动佩鲁西亚战争，自称要恢复共和。投降后被屋大维宽恕，派往西班牙任职，不久死去。'],
  ['文提迪乌斯', 'antony', 'Publius Ventidius Bassus', '?–?', '皮凯努姆人，童年在同盟者战争中被俘，随母亲在凯旋式上游街，后来以替军队承办骡车起家，被恺撒提拔。恺撒死后追随安东尼，前 43 年任补缺执政官。前 39 至前 38 年三次击败帕提亚人，杀死帕提亚王子帕科鲁斯，是第一个因战胜帕提亚而举行凯旋式的罗马人，从俘虏到凯旋，罗马人津津乐道。'],
  ['马库斯·布鲁图斯', 'liberatores', '', '', ''],
  ['卡西乌斯', 'liberatores', '', '', ''],
  ['德奇穆斯·布鲁图斯', 'liberatores', '', '', ''],
  ['塞克斯图斯·庞培', 'sextus', 'Sextus Pompeius Magnus Pius', '约前67–前35', '庞培的幼子，父亲死在埃及时他就在船上目睹。蒙达之战后在西班牙打游击，恺撒死后获元老院任命统率舰队，占据西西里，收容被公敌宣告的人与逃亡奴隶，自称“海神之子”，多次封锁意大利的粮道。前 36 年在瑙洛库斯被阿格里帕击败，逃往小亚细亚，被安东尼的部将处死。'],
  ['克娄巴特拉七世', 'ptolemy', '', '', ''],
  ['恺撒里昂', 'ptolemy', 'Ptolemy XV Caesar', '前47–前30', '克娄巴特拉七世的长子，据说是恺撒的儿子，“恺撒里昂”意为“小恺撒”。三岁起与母亲共治埃及，前 34 年在亚历山大里亚的赠礼中被安东尼宣布为恺撒的合法儿子与“万王之王”。亚克兴战后母亲送他经红海逃往印度，他被骗回亚历山大里亚处死，屋大维的谋士说：“恺撒太多了不好。”'],
  ['克娄巴特拉·塞勒涅', 'ptolemy', 'Cleopatra Selene II', '前40–约公元5', '克娄巴特拉七世与安东尼的女儿，与孪生兄弟亚历山大·赫利俄斯分别以月亮与太阳命名。在亚历山大里亚的赠礼中得到昔兰尼。父母死后被带到罗马，在屋大维娅家中长大，后嫁给毛里塔尼亚国王尤巴二世，在凯撒里亚的宫廷里延续着托勒密家族的传统。'],
  ['尤巴二世', 'mauri', 'Juba II', '约前48–公元23', '努米底亚国王尤巴一世之子，父亲在塔普苏斯败亡后，幼年的他在恺撒的凯旋式上游街，此后在罗马长大，受到良好的希腊式教育，成了罗马公民。曾随屋大维出征，前 25 年被封为毛里塔尼亚国王，娶克娄巴特拉·塞勒涅，以凯撒里亚为都城，用希腊文写过多部历史、地理与艺术著作，派人探访加那利群岛。'],
  ['许尔堪二世', 'judaea', '', '', ''],
  ['玛他提亚·安提柯', 'judaea', 'Antigonus II Mattathias', '?–前37', '哈斯蒙尼王朝的末代国王，阿里斯托布鲁斯二世之子。前 40 年帕提亚入侵时，许诺给帕提亚人一千塔兰特与五百名妇女，被扶上耶路撒冷的王位，割掉伯父许尔堪二世的耳朵使他不能再任大祭司。前 37 年耶路撒冷被希律与罗马人攻陷，他被押往安条克，安东尼下令将他斩首，据说这是罗马人第一次处死一位国王。'],
  ['大希律', 'judaea', 'Herod the Great', '前73–前4', '以土买人，父亲安提帕特是许尔堪二世的权臣，母亲是纳巴泰人。前 40 年逃往罗马，被元老院立为犹太国王，前 37 年夺取耶路撒冷，此后在安东尼与屋大维之间巧妙周旋，统治三十多年。他重建了耶路撒冷圣殿，修建了凯撒里亚、马萨达、希律堡等大批工程，却极度猜忌，处死了妻子米利暗、岳母与三个儿子。《马太福音》中屠杀伯利恒婴孩的就是他。'],
  ['亚基老', 'judaea', 'Herod Archelaus', '前23–约公元18', '大希律与撒玛利亚妻子马尔塔塞之子。父亲死后得到犹太、撒玛利亚与以土买，称“民族首领”，奥古斯都许诺他治理得好便可称王。即位之初就在逾越节屠杀了三千人，统治残暴，公元 6 年被犹太人与撒玛利亚人联名控告，被奥古斯都废黜，流放到高卢的维埃纳。'],
  ['希律·安提帕', 'judaea', 'Herod Antipas', '前20以前–公元39以后', '大希律与马尔塔塞之子，亚基老的弟弟，统治加利利与佩利亚四十多年。他在加利利湖边建立了以提比略命名的提比里亚城，娶了异母兄弟的妻子希罗底，因此斩了施洗约翰。《路加福音》说彼拉多曾把耶稣送到他那里受审。'],
  ['耶稣', 'judaea', 'Jesus of Nazareth', '约前6/前4–约公元30/33', '加利利拿撒勒的犹太人，据福音书生于希律王晚年的伯利恒，在拿撒勒长大。约公元 28 年起在加利利一带传道、治病，宣讲上帝之国，收了十二门徒，在耶路撒冷的逾越节期间被犹太长官本丢·彼拉多钉死在十字架上。他的门徒宣称他已复活，由此产生了基督教。'],
  ['阿敏塔斯', 'galatia', 'Amyntas of Galatia', '?–前25', '加拉太国王德奥塔鲁斯的书记，腓立比之战时率领加拉太骑兵为布鲁图斯作战，临阵倒向安东尼。前 37 年被安东尼立为加拉太、吕考尼亚与皮西迪亚的国王，亚克兴战前又带着两千骑兵投奔屋大维，保住了王位。前 25 年征讨托罗斯山区的部落时中伏被杀，王国改为加拉太行省。'],
  ['波勒蒙一世', 'pontus', 'Polemon I', '?–前8', '老底嘉的演说家之子，因抵御帕提亚入侵有功，被安东尼先后封为西里西亚一部分与本都的国王，曾随安东尼远征帕提亚，被米底人俘虏。亚克兴之后归顺屋大维，后来又娶博斯普鲁斯女王狄娜米斯，统治黑海北岸，在征讨反叛的部落时被杀。'],
  ['阿尔凯劳斯', 'cappadocia', 'Archelaus of Cappadocia', '?–公元17', '本都将领阿尔凯劳斯的曾孙。前 36 年被安东尼立为卡帕多西亚国王，亚克兴之后被屋大维保留，统治五十年，还得到小亚美尼亚与西里西亚的一部分。晚年得罪了提比略，公元 17 年被召到罗马受审，不久死去，王国改为行省。'],
  ['阿尔塔瓦兹德二世', 'armenia', 'Artavasdes II', '?–前31', '亚美尼亚国王，提格兰二世之子，通希腊文，写过希腊语悲剧。前 53 年倒向帕提亚，据说克拉苏的头被送到帕提亚宫廷时正在演出他翻译的欧里庇得斯《酒神的伴侣》。前 36 年随安东尼远征，中途撤走骑兵，前 34 年被安东尼诱捕，在亚历山大里亚的凯旋式上戴着银链游街，亚克兴之后被克娄巴特拉处死。'],
  ['阿尔塔夏斯二世', 'armenia', 'Artaxias II', '?–前20', '阿尔塔瓦兹德二世之子，父亲被安东尼俘虏后逃往帕提亚，亚克兴之后在帕提亚人帮助下回国称王，处死了国内的罗马人。前 20 年提比略带兵前来时，他被国内的亲罗马派杀死，弟弟提格兰三世被罗马扶上王位。'],
  ['帕科鲁斯', 'parthia', 'Pacorus I', '?–前38', '帕提亚国王奥罗德斯二世的长子与共治者，以宽厚得到叙利亚人的爱戴。前 40 年与小拉比努斯入侵罗马的叙利亚与小亚细亚，前 38 年在金达洛斯败于文提迪乌斯，战死。父亲因此悲痛欲绝，传位给了次子弗拉阿特斯四世。'],
  ['弗拉阿特斯四世', 'parthia', 'Phraates IV', '?–前2', '帕提亚国王，约前 37 年即位后杀死父亲奥罗德斯二世与三十个兄弟。前 36 年在米底击退安东尼，此后多次被争位者赶下王位，靠斯基泰人的帮助复位。前 20 年交还克拉苏与安东尼丢失的军旗，把四个儿子送到罗马作人质，晚年被奥古斯都赠送的意大利女奴穆萨与其子毒死。'],
  ['小拉比努斯', 'parthia', 'Quintus Labienus', '?–前39', '恺撒副将、后投庞培的拉比努斯之子。腓立比之战前被布鲁图斯与卡西乌斯派往帕提亚求援，共和派败亡后留在帕提亚，前 40 年与帕科鲁斯入侵叙利亚与小亚细亚，自称“帕提亚征服者”，铸币上刻着帕提亚的战马。前 39 年被文提迪乌斯击败，躲藏在西里西亚，被搜出处死。'],
  ['马罗博杜乌斯', 'marcomanni', 'Maroboduus', '约前30–公元37', '马科曼尼人的贵族，少年时在罗马生活过，熟悉罗马的军事与统治。约前 9 年德鲁苏斯进攻时，他带领族人迁到波希米亚，统一周边诸部，建立了拥有七万步兵与四千骑兵的王国。公元 6 年险些遭到提比略十二个军团的夹攻，因大起义得以与罗马议和。条顿堡之后拒绝与阿米尼乌斯联手，后来被推翻，在拉文纳流亡十八年而死。'],
  ['阿米尼乌斯', 'germani', 'Arminius', '约前18–公元21', '切鲁西人首领的儿子，青年时在罗马军中统领日耳曼辅助部队，获得罗马公民权与骑士身份。公元 9 年在条顿堡森林伏击瓦卢斯，全歼三个军团，使罗马放弃了征服莱茵河以东的计划。此后与日耳曼尼库斯连年交战，又击败马罗博杜乌斯，最后被想称王的同族亲人杀死。十九世纪的德国人奉他为民族英雄，称他“赫尔曼”。'],
];
